Here is the root cause:
The GRP_ACK_MSG handler in tipc_group_proto_rcv() unconditionally decrements bc_ackers on every inbound group ACK without verifying that the ACK sequence number is newer than the member's current bc_acked. This allows duplicate or stale ACKs to decrement bc_ackers repeatedly, causing an underflow (wrap to 65535) of the u16 counter, which incorrectly signals broadcast congestion and blocks future group broadcasts until group recreation.

Here is the patch:

 void tipc_group_proto_rcv(struct tipc_group *grp, bool *usr_wakeup,
 			  struct tipc_msg *hdr, struct sk_buff_head *inputq,
 			  struct sk_buff_head *xmitq)
 {
 	u32 node = msg_orignode(hdr);
 	u32 port = msg_origport(hdr);
 	struct tipc_member *m, *pm;
 	u16 remitted, in_flight;
+	u16 acked;

 	if (!grp)
 		return;

 	if (grp->scope == TIPC_NODE_SCOPE && node != tipc_own_addr(grp->net))
 		return;

 	m = tipc_group_find_member(grp, node, port);

 	switch (msg_type(hdr)) {
 	case GRP_JOIN_MSG:
 		if (!m)
 			m = tipc_group_create_member(grp, node, port,
 						     0, MBR_JOINING);
 		if (!m)
 			return;
 		m->bc_syncpt = msg_grp_bc_syncpt(hdr);
 		m->bc_rcv_nxt = m->bc_syncpt;
 		m->window += msg_adv_win(hdr);

 		/* Wait until PUBLISH event is received if necessary */
 		if (m->state != MBR_PUBLISHED)
 			return;

 		/* Member can be taken into service */
 		m->state = MBR_JOINED;
 		tipc_group_open(m, usr_wakeup);
 		tipc_group_update_member(m, 0);
 		tipc_group_proto_xmit(grp, m, GRP_ADV_MSG, xmitq);
 		tipc_group_create_event(grp, m, TIPC_PUBLISHED,
 					m->bc_syncpt, inputq);
 		return;
 	case GRP_LEAVE_MSG:
 		if (!m)
 			return;
 		m->bc_syncpt = msg_grp_bc_syncpt(hdr);
 		list_del_init(&m->list);
 		tipc_group_open(m, usr_wakeup);
 		tipc_group_decr_active(grp, m);
 		m->state = MBR_LEAVING;
 		tipc_group_create_event(grp, m, TIPC_WITHDRAWN,
 					m->bc_syncpt, inputq);
 		return;
 	case GRP_ADV_MSG:
 		if (!m)
 			return;
 		m->window += msg_adv_win(hdr);
 		tipc_group_open(m, usr_wakeup);
 		return;
 	case GRP_ACK_MSG:
 		if (!m)
 			return;
-		m->bc_acked = msg_grp_bc_acked(hdr);
+		acked = msg_grp_bc_acked(hdr);
+		if (less_eq(acked, m->bc_acked))
+			return;
+		m->bc_acked = acked;
 		if (--grp->bc_ackers)
 			return;
 		list_del_init(&m->small_win);
 		*m->group->open = true;
 		*usr_wakeup = true;
 		tipc_group_update_member(m, 0);
 		return;
 	case GRP_RECLAIM_MSG:
 		if (!m)
 			return;
 		tipc_group_proto_xmit(grp, m, GRP_REMIT_MSG, xmitq);
 		m->window = ADV_IDLE;
 		tipc_group_open(m, usr_wakeup);
 		return;
 	case GRP_REMIT_MSG:
 		if (!m || m->state != MBR_RECLAIMING)
 			return;

 		remitted = msg_grp_remitted(hdr);

 		/* Messages preceding the REMIT still in receive queue */
 		if (m->advertised > remitted) {
 			m->state = MBR_REMITTED;
 			in_flight = m->advertised - remitted;
 			m->advertised = ADV_IDLE + in_flight;
 			return;
 		}
 		/* This should never happen */
 		if (m->advertised < remitted)
 			pr_warn_ratelimited("Unexpected REMIT msg\n");

 		/* All messages preceding the REMIT have been read */
 		m->state = MBR_JOINED;
 		grp->active_cnt--;
 		m->advertised = ADV_IDLE;

 		/* Set oldest pending member to active and advertise */
 		if (list_empty(&grp->pending))
 			return;
 		pm = list_first_entry(&grp->pending, struct tipc_member, list);
 		pm->state = MBR_ACTIVE;
 		list_move_tail(&pm->list, &grp->active);
 		grp->active_cnt++;
 		if (pm->advertised <= (ADV_ACTIVE * 3 / 4))
 			tipc_group_proto_xmit(grp, pm, GRP_ADV_MSG, xmitq);
 		return;
 	default:
 		pr_warn("Received unknown GROUP_PROTO message\n");
 	}
 }



